DECLARE
vn_count NUMBER;
BEGIN
SELECT COUNT(*) INTO vn_count
FROM user_tables
WHERE table_name = 'TENANT_P_FEX_PRODUCT';
IF vn_count = 0 THEN
    EXECUTE IMMEDIATE 'CREATE TABLE TENANT_P_FEX_PRODUCT (
        ID VARCHAR2(32) NOT NULL,
        PRO_LEVEL VARCHAR2(1) NOT NULL,
        TRAN_TYPE VARCHAR2(1) NOT NULL,
        PRO_NAME VARCHAR2(60) NOT NULL,
        PRO_DESC VARCHAR2(100) NULL,
        PRO_ID VARCHAR2(65) NULL,
        FEX_BUS_TYPE VARCHAR2(1) NULL,
        FEX_TRAN_TYPE VARCHAR2(1) NULL,
        DELIVERY_TYPE VARCHAR2(1) NULL,
        DELIVERY_CUR_ID VARCHAR2(32) NULL,
        IS_ALLOWED_DELIVERY VARCHAR2(1) DEFAULT ''0'' NULL,
        IS_ALLOWED_SETTLE VARCHAR2(1) DEFAULT ''0'' NULL,
        BUY_CUR_ID VARCHAR2(32) NULL,
        SELL_CUR_ID VARCHAR2(32) NULL,
        NON_WORKDAY_RULE VARCHAR2(30) NULL,
        TRANGROUP_RULE_ID VARCHAR2(32) NULL,
        IS_ALLOWED_CHANGE VARCHAR2(1) NULL,
        VALID_SIGN VARCHAR2(1) DEFAULT ''1'' NULL,
        RMK VARCHAR2(200) NULL,
        CREATE_DATE DATE NULL,
        CREATE_BY VARCHAR2(50) NULL,
        UPDATE_DATE DATE NULL,
        UPDATE_BY VARCHAR2(50) NULL,
        FEX_OPTION1 VARCHAR2(1) NULL,
        FEX_OPTION2 VARCHAR2(1) NULL,
        FEX_OPTION3 VARCHAR2(1) NULL,
        FEX_OPTION_TYPE VARCHAR2(1) NULL,
        FEX_OPTION_RATE VARCHAR2(1) NULL,
        REFUND_TIME VARCHAR2(1) NULL,
        DAYS_RULE VARCHAR2(1) NULL,
        VALID_STANDARD VARCHAR2(1) NULL,
        TRAN_SETTLE_METHOD VARCHAR2(1) NULL,
        IS_SHOW_AGENT VARCHAR2(1) NULL,
        IS_SHOW_CLEAR_HOUSE VARCHAR2(1) NULL,
        IS_AUTO_DELIVERY VARCHAR2(1) DEFAULT ''0'' NOT NULL,
        IS_ALLOWED_DEL VARCHAR2(1) DEFAULT ''1'' NULL,
        IS_INIT CHAR(1) DEFAULT ''1'' NULL,
        CONSTRAINT PK_TENANT_P_FEX_PRODUCT PRIMARY KEY (ID)
    )';
    EXECUTE IMMEDIATE 'COMMENT ON TABLE TENANT_P_FEX_PRODUCT IS ''租户外汇产品预置表''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.PRO_LEVEL IS ''层级 0-产品组 1-产品''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.TRAN_TYPE IS ''交易类型 1-外汇交易、2-外汇期权交易、3-调拨交易、4-资金收付交易、5-货币市场交易、6-债券交易''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.PRO_NAME IS ''名称''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.PRO_DESC IS ''描述''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.PRO_ID IS ''所属组ID''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.FEX_BUS_TYPE IS ''外汇业务类型 1-结汇、2-售汇、3-外汇买卖''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.FEX_TRAN_TYPE IS ''外汇交易类型 0-即期、1-远期''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.DELIVERY_TYPE IS ''交割类型 0-本金交割、1-无本金交割''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.DELIVERY_CUR_ID IS ''交割币种''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.IS_ALLOWED_DELIVERY IS ''是否允许多次交割 1-是 0-否''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.IS_ALLOWED_SETTLE IS ''非工作日是否允许结算 1-是 0-否''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.NON_WORKDAY_RULE IS ''非工作日适用原则 1-币种、2-交易主体单位所在地、3-主体银行所在地、4-交易对手所在地''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.IS_ALLOWED_CHANGE IS ''交易组规则是否可以在交易组中更改 1-是 0-否''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.VALID_SIGN IS ''有效标志 1-是 0-否''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.IS_AUTO_DELIVERY IS ''即期是否自动交割 1-是 0-否''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.IS_ALLOWED_DEL IS ''是否可以删除 1-是 0-否''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_P_FEX_PRODUCT.IS_INIT IS ''是否初始化''';
END IF;
END;
/

