DECLARE
v_table_exists NUMBER;
BEGIN
SELECT COUNT(*) INTO v_table_exists
FROM user_tables
WHERE table_name = 'TENANT_PRE_TABLE_RECORD';

IF v_table_exists = 0 THEN
        EXECUTE IMMEDIATE 'CREATE TABLE TENANT_PRE_TABLE_RECORD (
            ID        VARCHAR2(32)  NOT NULL,
            USER_ID   VARCHAR2(32)  NULL,
            TABLE_KEY VARCHAR2(255) NOT NULL,
            CONTENT   CLOB          NULL,
            IS_INIT   VARCHAR2(1)   DEFAULT ''1'' NOT NULL,
            CONSTRAINT PK_TENANT_PRE_TABLE_RECORD PRIMARY KEY (ID),
            CONSTRAINT UK_TP_TABLE_RECORD_KEY UNIQUE (TABLE_KEY)
        )';
EXECUTE IMMEDIATE 'COMMENT ON TABLE TENANT_PRE_TABLE_RECORD IS ''租户前台表格默认配置预置表''';
EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_PRE_TABLE_RECORD.ID IS ''主键''';
EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_PRE_TABLE_RECORD.USER_ID IS ''用户ID''';
EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_PRE_TABLE_RECORD.TABLE_KEY IS ''表格的URL作为KEY''';
EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_PRE_TABLE_RECORD.CONTENT IS ''用户习惯记录JSON结构''';
EXECUTE IMMEDIATE 'COMMENT ON COLUMN TENANT_PRE_TABLE_RECORD.IS_INIT IS ''是否需要给租户初始化''';
END IF;
END;
/

